import java.util.Scanner;

public class Main {
    public static int findSubstring(String s1, String s2, int start) {
        for (int i = start; i <= s1.length() - s2.length(); i++) {
            if (s1.charAt(i) == s2.charAt(0)) {
                boolean match = true;
                for (int j = 1; j < s2.length(); j++) {
                    if (s1.charAt(i + j) != s2.charAt(j)) {
                        match = false;
                        break;
                    }
                }
                if (match) return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s1 = scanner.nextLine();
        String s2;
        int pos = findSubstring(s1, "at", 1);
        s2 = s1.substring(0, pos) + '@' + s1.substring(pos + 2);
        int index = findSubstring(s2, "dot", 1);
        int lastPos = 0;
        StringBuilder result = new StringBuilder();
        while (index != -1 && index < s2.length() - 3) {
            result.append(s2.substring(lastPos, index)).append(".");
            lastPos = index + 3;
            index = findSubstring(s2, "dot", lastPos);
        }
        result.append(s2.substring(lastPos));
        System.out.print(result.toString());
        scanner.close();
    }
}
